?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý bài viết</title><link rel="stylesheet" href="../css/style.css?v=20261110"></head><body><main class="admin-wrap"><section class="admin-panel admin-wide"><div class="admin-top"><h1>Quản trị Truyện Đêm</h1><a href="stories.php?list=short">Đăng truyện ngắn</a><a href="stories.php?list=serial">Truyện nhiều chương</a><a href="stories.php?list=all">Quản lý tất cả truyện</a><a href="members.php">Quản lý thành viên</a><a href="logout.php">Đăng xuất</a></div><p>Xin chào <?= e($_SESSION['blog_admin_name'] ?? 'quản trị viên') ?> · <a href="../blog.php" target="_blank">Xem website truyện</a></p><?php if(isset($_GET['saved'])): ?><p class="admin-success">✓ Bài viết đã được lưu.</p><?php endif; ?><p><a class="go admin-new" href="edit.php">＋ Đăng bài mới</a></p><div class="admin-table"><?php if(!$posts): ?><p>Chưa có bài viết nào. Hãy nhấn “Đăng bài mới” để bắt đầu.</p><?php else: ?><table><thead><tr><th>Bài viết</th><th>Trạng thái</th><th>Ngày tạo</th><th>Thao tác</th></tr></thead><tbody><?php foreach($posts as $p): ?><tr><td><?= e($p['title']) ?></td><td><?= $p['status']==='published'?'Đã xuất bản':'Bản nháp' ?></td><td><?= e(date('d/m/Y',strtotime($p['created_at']))) ?></td><td><a href="edit.php?id=<?= (int)$p['id'] ?>">Sửa</a> · <form class="inline-form" method="post" action="delete.php" onsubmit="return confirm('Xóa bài viết này?')"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="lnk" type="submit">Xóa</button></form><?php if($p['status']==='published'): ?> · <a href="../post.php?slug=<?= rawurlencode($p['slug']) ?>" target="_blank">Xem</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></section></main></body></html>